}, []);

// ✅ Correct: Name the function so removeEventListener references the exact same pointer
useEffect(() => {
  function onScroll() { handleScroll(); }
  window.addEventListener("scroll", onScroll);
  return () => window.removeEventListener("scroll", onScroll);
}, []);

import { useState, useEffect } from "react";

function Clock() {
  const [time, setTime] = useState(new Date().toLocaleTimeString());

  useEffect(() => {
    const id = setInterval(() => {
      setTime(new Date().toLocaleTimeString());
    }, 1000);

    return () => {
      clearInterval(id);
    };
  }, []);

  return (
    <div style={{ padding: "12px", border: "1px solid #10b981", borderRadius: "6px" }}>
      ⏰ Active Clock: <strong>{time}</strong>
    </div>
  );
}

export default function App() {
