      >
        {showClock ? "Unmount Clock Component" : "Mount Clock Component"}
      </button>

      {showClock ? <Clock /> : <p style={{ color: "#64748b" }}>Clock unmounted. Interval cleared cleanly!</p>}
    </div>
  );
}

