import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
  ForbiddenException,
} from '@nestjs/common';

@Injectable()
export class RolesGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const user = request.user;

    // 1. Authentication check
    if (!user) {
      throw new UnauthorizedException('Authentication required');
    }

    // 2. Authorization check
    if (user.role !== 'admin') {
      throw new ForbiddenException('Admin role required');
    }

    return true;
  }
}

// Bad: Confusing 401 and 403
if (user.role !== 'admin') {
  throw new UnauthorizedException(); // Misleading: implies they need to log in again!
}

// Clean: Correct HTTP status codes
if (!user) {
  throw new UnauthorizedException('Sign in required'); // 401
}
if (user.role !== 'admin') {
  throw new ForbiddenException('Admin role required'); // 403
}

import { Injectable, CanActivate, ExecutionContext, UnauthorizedException, ForbiddenException } from '@nestjs/common';

@Injectable()
export class AdminGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest();
    const user = req.user;

    if (!user) throw new UnauthorizedException('Please log in');
    if (user.role !== 'admin') throw new ForbiddenException('Access denied: Admins only');

    return true;
  }
}

