let course = {
  _id: "crs_1",
  title: "React Basics",
  price: 600,
  enrolledCount: 10,
  isPublished: true
};

function updateOne(doc, update) {
  const result = { ...doc };
  if (update.$set) {
    Object.assign(result, update.$set);
  }
  if (update.$inc) {
    for (const [key, val] of Object.entries(update.$inc)) {
      result[key] = (result[key] || 0) + val;
    }
  }
  return result;
}

