function lookup(sourceList, targetList, localKey, foreignKey, asField) {
  return sourceList.map(item => {
    const matches = targetList.filter(t => t[foreignKey] === item[localKey]);
    return {
      ...item,
      [asField]: matches
    };
  });
}

