  private state: CounterState;
  constructor() {
    this.state = initialState;
  }

  getState() {
    return this.state;
  }

  dispatch(action: Action) {
    console.log(`[Dispatch] Action: ${action.type}`, action.payload ? action.payload : "");
    this.state = counterReducer(this.state, action);
    console.log("[Store] Next State:", this.state);
  }
}

