// Standalone createSlice Mental Model Simulation
function createSliceModel({ name, initialState, reducers }) {
  const actions = {};

  // Generate action creators
  for (const key of Object.keys(reducers)) {
    const type = `${name}/${key}`;
    actions[key] = (payload) => ({ type, payload });
  }

  // Reducer function
  const reducer = (state = initialState, action) => {
    const actionKey = action.type.replace(`${name}/`, "");
    const reducerFn = reducers[actionKey];
    if (reducerFn) {
      // Simulate Immer by cloning state
      const draft = JSON.parse(JSON.stringify(state));
      const result = reducerFn(draft, action);
      return result !== undefined ? result : draft;
    }
    return state;
  };

  return { name, actions, reducer };
}

