    switch (action.type) {
      case "todos/addTodo":
        return {
          ...state,
          items: [
            ...state.items,
            { id: Date.now(), text: action.payload, completed: false }
          ]
        };
      case "todos/toggleTodo":
        return {
          ...state,
          items: state.items.map(t =>
            t.id === action.payload ? { ...t, completed: !t.completed } : t
          )
        };
      default:
        return state;
    }
  };

  return { actions, reducer };
}

