// Simulated Component Selector Hook
function simulateUseSelector<T>(selector: (state: AppState) => T, componentName: string) {
  let previousValue = selector(currentState);
  console.log(`[${componentName}] Initial value:`, previousValue);

  return function onStoreUpdate(nextState: AppState) {
    const nextValue = selector(nextState);
    if (nextValue !== previousValue) {
      console.log(`[${componentName}] Value CHANGED from:`, previousValue, "->", nextValue, "(RE-RENDER!)");
