function createMemoizedFilter(threshold) {
  let lastItems = null;
  let lastResult = null;

  return function (items) {
    if (items === lastItems) {
      console.log("-> [CACHE HIT] Returning cached reference.");
      return lastResult;
    }
    console.log("-> [CALCULATING] Filtering items...");
    lastItems = items;
    lastResult = items.filter((item) => item.price > threshold);
    return lastResult;
  };
}

