// Tag Invalidation simulator
class CacheManager {
  constructor() {
    this.cache = new Map();
    this.tagSubscriptions = new Map();
  }

  provideTag(queryName, tag) {
    if (!this.tagSubscriptions.has(tag)) this.tagSubscriptions.set(tag, new Set());
    this.tagSubscriptions.get(tag).add(queryName);
    console.log(`[Cache] Query "${queryName}" subscribed to tag "${tag}"`);
  }

  invalidateTag(tag) {
    console.log(`[Cache] Tag "${tag}" INVALIDATED!`);
    const affected = this.tagSubscriptions.get(tag) || [];
    affected.forEach((query) => {
      console.log(` -> Automatically triggering background refetch for: ${query}`);
    });
  }
}

